"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[54455],{46586(e,a,o){o.r(a),o.d(a,{assets:()=>c,contentTitle:()=>t,default:()=>u,frontMatter:()=>i,metadata:()=>n,toc:()=>l});const n=JSON.parse('{"id":"cursos/docker/modulos/docker-cloud/cuestionario","title":"Cuestionario M23 \u2014 Docker en Cloud","description":"Instrucci\xf3n: Estas preguntas eval\xfaan si investigaste m\xe1s all\xe1 del","source":"@site/docs/cursos/docker/modulos/23-docker-cloud/cuestionario.md","sourceDirName":"cursos/docker/modulos/23-docker-cloud","slug":"/cursos/docker/modulos/docker-cloud/cuestionario","permalink":"/sasf-temarios/cursos/docker/modulos/docker-cloud/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/docker/modulos/docker-cloud/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/docker/modulos/docker-cloud/ejercicio"}}');var s=o(74848),r=o(28453);const i={sidebar_label:"Cuestionario"},t="Cuestionario M23 \u2014 Docker en Cloud",c={},l=[{value:"1. [Investigar] \xbfQu\xe9 es exactamente &quot;Firecracker&quot; y c\xf3mo AWS lo usa para Fargate y Lambda? \xbfQu\xe9 lo hace diferente de una VM tradicional?",id:"1-investigar-qu\xe9-es-exactamente-firecracker-y-c\xf3mo-aws-lo-usa-para-fargate-y-lambda-qu\xe9-lo-hace-diferente-de-una-vm-tradicional",level:3},{value:"2. [Investigar] \xbfQu\xe9 es exactamente &quot;Karpenter&quot; y c\xf3mo mejora el auto-scaling de nodos en Kubernetes comparado con Cluster Autoscaler?",id:"2-investigar-qu\xe9-es-exactamente-karpenter-y-c\xf3mo-mejora-el-auto-scaling-de-nodos-en-kubernetes-comparado-con-cluster-autoscaler",level:3},{value:"3. [Investigar] \xbfQu\xe9 es exactamente &quot;Knative&quot; y c\xf3mo se relaciona con Cloud Run? \xbfQu\xe9 proporciona Knative que K8s nativo no tiene?",id:"3-investigar-qu\xe9-es-exactamente-knative-y-c\xf3mo-se-relaciona-con-cloud-run-qu\xe9-proporciona-knative-que-k8s-nativo-no-tiene",level:3},{value:"4. [Investigar] \xbfQu\xe9 es exactamente &quot;FinOps&quot; en el contexto de contenedores cloud? \xbfC\xf3mo se optimizan costos de ECS/EKS/Cloud Run?",id:"4-investigar-qu\xe9-es-exactamente-finops-en-el-contexto-de-contenedores-cloud-c\xf3mo-se-optimizan-costos-de-ecsekscloud-run",level:3},{value:"5. [Conectar] La clase menciona ECS, EKS, ACI, Cloud Run. \xbfC\xf3mo elegir entre un managed K8s (EKS/AKS/GKE) y un serverless container service (Fargate/Cloud Run/ACI)?",id:"5-conectar-la-clase-menciona-ecs-eks-aci-cloud-run-c\xf3mo-elegir-entre-un-managed-k8s-eksaksgke-y-un-serverless-container-service-fargatecloud-runaci",level:3},{value:"6. [Conectar] \xbfC\xf3mo funciona el networking en AWS Fargate con el modo <code>awsvpc</code>? \xbfQu\xe9 implicaciones tiene que cada task tenga su propia ENI?",id:"6-conectar-c\xf3mo-funciona-el-networking-en-aws-fargate-con-el-modo-awsvpc-qu\xe9-implicaciones-tiene-que-cada-task-tenga-su-propia-eni",level:3},{value:"7. [Conectar] \xbfC\xf3mo funciona exactamente <code>gcloud run deploy</code> con <code>--no-traffic</code> y traffic splitting? \xbfC\xf3mo implementar blue/green deployment en Cloud Run?",id:"7-conectar-c\xf3mo-funciona-exactamente-gcloud-run-deploy-con---no-traffic-y-traffic-splitting-c\xf3mo-implementar-bluegreen-deployment-en-cloud-run",level:3},{value:"8. [Cuestionar] \xbfEs Terraform la herramienta correcta para gestionar infraestructura Docker/cloud en 2025 o Pulumi/Crossplane/CDKTF son superiores?",id:"8-cuestionar-es-terraform-la-herramienta-correcta-para-gestionar-infraestructura-dockercloud-en-2025-o-pulumicrossplanecdktf-son-superiores",level:3},{value:"9. [Cuestionar] \xbfDeber\xedas usar un solo cloud provider para tus contenedores o adoptar multi-cloud desde el principio? \xbfCu\xe1ndo vale la pena la complejidad de multi-cloud?",id:"9-cuestionar-deber\xedas-usar-un-solo-cloud-provider-para-tus-contenedores-o-adoptar-multi-cloud-desde-el-principio-cu\xe1ndo-vale-la-pena-la-complejidad-de-multi-cloud",level:3},{value:"10. [Cuestionar] \xbfSon los &quot;serverless containers&quot; (Cloud Run, Fargate) el futuro, o Kubernetes gestionado (EKS, GKE) seguir\xe1 siendo el est\xe1ndar para aplicaciones enterprise?",id:"10-cuestionar-son-los-serverless-containers-cloud-run-fargate-el-futuro-o-kubernetes-gestionado-eks-gke-seguir\xe1-siendo-el-est\xe1ndar-para-aplicaciones-enterprise",level:3}];function d(e){const a={code:"code",h1:"h1",h3:"h3",header:"header",hr:"hr",p:"p",strong:"strong",...(0,r.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(a.header,{children:(0,s.jsx)(a.h1,{id:"cuestionario-m23--docker-en-cloud",children:"Cuestionario M23 \u2014 Docker en Cloud"})}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Instrucci\xf3n"}),": Estas preguntas eval\xfaan si investigaste m\xe1s all\xe1 del\r\ncontenido de la clase. No alcanza con lo visto en ",(0,s.jsx)(a.code,{children:"clase.md"}),".\r\nFundament\xe1 tus respuestas con fuentes, autores o ejemplos concretos."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"1-investigar-qu\xe9-es-exactamente-firecracker-y-c\xf3mo-aws-lo-usa-para-fargate-y-lambda-qu\xe9-lo-hace-diferente-de-una-vm-tradicional",children:'1. [Investigar] \xbfQu\xe9 es exactamente "Firecracker" y c\xf3mo AWS lo usa para Fargate y Lambda? \xbfQu\xe9 lo hace diferente de una VM tradicional?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": Firecracker (AWS, 2018, open-source) es un micro-VMM (Virtual Machine Monitor) dise\xf1ado espec\xedficamente para ejecutar cargas de trabajo serverless y contenedores con la velocidad de un contenedor y la seguridad de una VM. Usa KVM (Kernel-based Virtual Machine) para crear micro-VMs que arrancan en ~125ms (vs segundos de una VM tradicional) y consumen ~5 MB de memoria overhead (vs cientos de MB de QEMU). Cada task de Fargate y cada ejecuci\xf3n de Lambda corre en su propia micro-VM Firecracker aislada. Diferencia con VM tradicional: no emula hardware completo (no BIOS, no VGA, no USB), solo expone dispositivos m\xednimos (virtio-net, virtio-block). Diferencia con contenedor: Firecracker virtualiza el kernel (cada micro-VM tiene su propio kernel Linux), lo que da m\xe1s aislamiento que namespaces (ideal para multi-tenant)."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': Firecracker fue desarrollado por AWS (Adrian Catangiu, Alexandra Gheorghe, et al.) basado en la experiencia de Google con gVisor y la necesidad de aislar Lambda functions de diferentes clientes en el mismo hardware. La combinaci\xf3n Fargate + Firecracker es lo que permite que AWS ofrezca "serverless containers" sin que los clientes compartan kernel (aislamiento fuerte). Rust (Firecracker est\xe1 escrito en Rust, m\xe1s seguro en memoria) y KVM son la base t\xe9cnica.']}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"2-investigar-qu\xe9-es-exactamente-karpenter-y-c\xf3mo-mejora-el-auto-scaling-de-nodos-en-kubernetes-comparado-con-cluster-autoscaler",children:'2. [Investigar] \xbfQu\xe9 es exactamente "Karpenter" y c\xf3mo mejora el auto-scaling de nodos en Kubernetes comparado con Cluster Autoscaler?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": Karpenter (AWS, 2021, open-source) es un auto-scaler de nodos para Kubernetes que reemplaza al Cluster Autoscaler con decisiones m\xe1s r\xe1pidas y flexibles. Diferencias: 1) CA espera que Pods est\xe9n en estado ",(0,s.jsx)(a.code,{children:"Pending"})," para escalar (reactivo, puede tardar minutos). Karpenter eval\xfaa constraints de scheduling en tiempo real y escala proactivamente (en segundos). 2) CA solo puede escalar Auto-Scaling Groups predefinidos. Karpenter selecciona din\xe1micamente el tipo de instancia \xf3ptimo (entre cientos de tipos EC2) basado en los Pods pendientes, sin predefinir grupos. 3) Karpenter consolida workloads agresivamente (reubica Pods a instancias m\xe1s baratas o m\xe1s eficientes, terminando las menos eficientes). 4) Karpenter puede manejar taints/tolerations, topology spread, y afinidad/anti-afinidad para scheduling \xf3ptimo."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': Karpenter fue creado por el equipo de AWS Kubernetes (Ellis Tarn, Prateek Gogia). Es open-source (Apache 2.0) pero con fuerte integraci\xf3n AWS (soporta EC2 y Fargate). La filosof\xeda: "just-in-time capacity". En lugar de gestionar grupos de nodos r\xedgidos, Karpenter crea la instancia exacta que los Pods necesitan, cuando la necesitan, y la elimina cuando no se necesita. Es la evoluci\xf3n del auto-scaling en K8s cloud.']}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"3-investigar-qu\xe9-es-exactamente-knative-y-c\xf3mo-se-relaciona-con-cloud-run-qu\xe9-proporciona-knative-que-k8s-nativo-no-tiene",children:'3. [Investigar] \xbfQu\xe9 es exactamente "Knative" y c\xf3mo se relaciona con Cloud Run? \xbfQu\xe9 proporciona Knative que K8s nativo no tiene?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": Knative (Google, 2018, proyecto CNCF) es un framework serverless sobre Kubernetes. Cloud Run (Google Cloud) es la versi\xf3n gestionada de Knative. Knative proporciona: 1) ",(0,s.jsx)(a.strong,{children:"Knative Serving"}),": abstracci\xf3n ",(0,s.jsx)(a.code,{children:"Service"})," que define una aplicaci\xf3n, su imagen, y escala autom\xe1ticamente a cero basado en tr\xe1fico HTTP. K8s nativo requiere Deployment + Service + HPA + Ingress (4 recursos) para funcionalidad similar, pero no escala a cero. 2) ",(0,s.jsx)(a.strong,{children:"Knative Eventing"}),": abstracciones para event-driven architectures (Broker, Trigger, Channel) que conectan fuentes de eventos (S3, Pub/Sub, Kafka) con servicios. 3) ",(0,s.jsx)(a.strong,{children:"Auto-TLS"}),": integraci\xf3n con cert-manager para TLS autom\xe1tico. 4) ",(0,s.jsx)(a.strong,{children:"Traffic splitting"}),": canary, blue/green deployments a nivel de revisi\xf3n. Knative convierte K8s en una plataforma PaaS similar a Heroku pero con toda la flexibilidad de K8s."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': Knative fue creado por Google (basado en la experiencia de App Engine y Cloud Run) en colaboraci\xf3n con Pivotal, IBM, Red Hat. Cloud Run for Anthos es Knative gestionado. La diferencia con K8s nativo: K8s te da bloques de construcci\xf3n (Deployment, Service), Knative te da una experiencia PaaS (especific\xe1s imagen + tr\xe1fico, y Knative maneja el resto). La escala a cero de Knative usa el "activator" (un proxy que encola requests mientras la instancia arranca) y el "autoscaler" (scale-to-zero cuando no hay requests por un per\xedodo configurable).']}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"4-investigar-qu\xe9-es-exactamente-finops-en-el-contexto-de-contenedores-cloud-c\xf3mo-se-optimizan-costos-de-ecsekscloud-run",children:'4. [Investigar] \xbfQu\xe9 es exactamente "FinOps" en el contexto de contenedores cloud? \xbfC\xf3mo se optimizan costos de ECS/EKS/Cloud Run?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": FinOps es la pr\xe1ctica de gestionar costos cloud de manera colaborativa entre finanzas, operaciones, y desarrollo. En contenedores cloud: 1) ",(0,s.jsx)(a.strong,{children:"Rightsizing"}),": ajustar CPU/memoria requests y limits basado en uso real (m\xe9tricas de Prometheus/CloudWatch), no en guesses. La mayor\xeda de los equipos sobredimensionan (requests 3-5x el uso real), desperdiciando 50-70% del costo. 2) ",(0,s.jsx)(a.strong,{children:"Spot/Preemptible instances"}),": para workloads tolerantes a fallos, usar instancias spot (60-90% descuento) en EKS/Karpenter o Fargate Spot. 3) ",(0,s.jsx)(a.strong,{children:"Scaling"}),": auto-scaling basado en m\xe9tricas reales (no solo CPU, sino tambi\xe9n requests por segundo, queue depth), y scale-to-zero para dev/staging (Cloud Run lo hace nativo, ECS con Fargate necesita scripting). 4) ",(0,s.jsx)(a.strong,{children:"Commitment discounts"}),": Savings Plans (AWS), Reserved Instances, Committed Use Discounts (GCP) para cargas estables. 5) ",(0,s.jsx)(a.strong,{children:"Tagging"}),": labels en todos los recursos para atribuir costos a equipos/proyectos."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': La FinOps Foundation (parte de la Linux Foundation) publica el "State of FinOps" anualmente. En 2024, el reporte muestra que el 65% de las organizaciones tienen "waste" en contenedores (recursos no usados). Herramientas como Kubecost, CloudHealth, y Vantage analizan el uso de recursos por namespace/Pod y recomiendan optimizaciones. Para contenedores, el mayor ahorro viene de rightsizing (ajustar requests/limits a uso real) y usar instancias spot para dev/staging.']}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"5-conectar-la-clase-menciona-ecs-eks-aci-cloud-run-c\xf3mo-elegir-entre-un-managed-k8s-eksaksgke-y-un-serverless-container-service-fargatecloud-runaci",children:"5. [Conectar] La clase menciona ECS, EKS, ACI, Cloud Run. \xbfC\xf3mo elegir entre un managed K8s (EKS/AKS/GKE) y un serverless container service (Fargate/Cloud Run/ACI)?"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": Elegir managed K8s (EKS/AKS/GKE) cuando: necesit\xe1s el ecosistema de K8s (Helm, operators, service mesh, CRDs), ten\xe9s workloads con requisitos de red complejos (NetworkPolicy, multi-cluster), quer\xe9s portabilidad multi-cloud (misma plataforma en AWS, Azure, on-prem), o tu aplicaci\xf3n ya est\xe1 empaquetada como Helm charts. Elegir serverless containers (Fargate/Cloud Run/ACI) cuando: quer\xe9s simplicidad operativa (cero gesti\xf3n de nodos/cluster), el tr\xe1fico es variable o intermitente (pagar solo por uso), la aplicaci\xf3n es stateless HTTP/gRPC (Cloud Run) o batch jobs (Fargate tasks), o el equipo es peque\xf1o y no tiene expertise en K8s. Cloud Run es ideal para APIs y microservicios HTTP. Fargate es ideal para tasks batch o aplicaciones que necesitan m\xe1s control (VPC, secrets). ACI es ideal en ecosistema Azure."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': La encuesta de CNCF (2024) muestra que el 50% de las organizaciones usan managed K8s y el 30% usan serverless containers. La tendencia es "managed K8s para la plataforma, serverless containers para las aplicaciones". Por ejemplo: equipo de plataforma gestiona EKS con Karpenter, los desarrolladores despliegan en Cloud Run (Knative sobre el mismo GKE) sin preocuparse por nodos.']}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsxs)(a.h3,{id:"6-conectar-c\xf3mo-funciona-el-networking-en-aws-fargate-con-el-modo-awsvpc-qu\xe9-implicaciones-tiene-que-cada-task-tenga-su-propia-eni",children:["6. [Conectar] \xbfC\xf3mo funciona el networking en AWS Fargate con el modo ",(0,s.jsx)(a.code,{children:"awsvpc"}),"? \xbfQu\xe9 implicaciones tiene que cada task tenga su propia ENI?"]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": En Fargate, el network mode ",(0,s.jsx)(a.code,{children:"awsvpc"})," asigna una ENI (Elastic Network Interface) DEDICADA a cada task (grupo de contenedores). La ENI tiene una IP privada de la VPC. Todos los contenedores de la task comparten esta ENI (pueden comunicarse via ",(0,s.jsx)(a.code,{children:"localhost"})," porque comparten network namespace). Implicaciones: 1) Cada task consume una ENI de la cuenta (l\xedmites de ENIs por regi\xf3n/instancia pueden ser restrictivos), 2) La task es directamente direccionable desde la VPC (sin NAT, sin overlay), simplificando conectividad con RDS, ElastiCache, etc., 3) Security Groups se aplican a nivel de ENI (a nivel de task, granular), 4) Los contenedores pueden usar cualquier puerto sin mapeo (la IP de la ENI expone todos los puertos directamente). El costo: ENIs son un recurso limitado (por defecto 5000 por regi\xf3n, ampliable). En K8s con CNI (AWS VPC CNI), cada Pod obtiene una ENI o una IP secundaria de una ENI compartida (m\xe1s eficiente en uso de ENIs)."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": ",(0,s.jsx)(a.code,{children:"awsvpc"})," es el modo de red de Fargate porque no ten\xe9s control del host (no pod\xe9s configurar bridges, iptables, o rutas). AWS abstrae el host y asigna una ENI directly-attached a la task via el hypervisor (Nitro). Esto es diferente al ",(0,s.jsx)(a.code,{children:"bridge"}),"/",(0,s.jsx)(a.code,{children:"host"})," de Docker standalone. La limitaci\xf3n pr\xe1ctica: con ",(0,s.jsx)(a.code,{children:"awsvpc"}),", cada task usa una ENI, y si ten\xe9s muchas tasks peque\xf1as, pod\xe9s agotar ENIs."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsxs)(a.h3,{id:"7-conectar-c\xf3mo-funciona-exactamente-gcloud-run-deploy-con---no-traffic-y-traffic-splitting-c\xf3mo-implementar-bluegreen-deployment-en-cloud-run",children:["7. [Conectar] \xbfC\xf3mo funciona exactamente ",(0,s.jsx)(a.code,{children:"gcloud run deploy"})," con ",(0,s.jsx)(a.code,{children:"--no-traffic"})," y traffic splitting? \xbfC\xf3mo implementar blue/green deployment en Cloud Run?"]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": ",(0,s.jsx)(a.code,{children:"gcloud run deploy --no-traffic"})," despliega una nueva revisi\xf3n pero NO le env\xeda tr\xe1fico (0%). La revisi\xf3n existente sigue recibiendo el 100%. Luego pod\xe9s: 1) ",(0,s.jsx)(a.code,{children:"gcloud run services update-traffic --to-revisions &#x3C;new-revision>=10"})," (canary: enviar 10% a la nueva revisi\xf3n), 2) Si funciona bien, aumentar a 50%, luego 100%, 3) Si falla, revertir a 100% a la revisi\xf3n anterior con ",(0,s.jsx)(a.code,{children:"--to-revisions &#x3C;old-revision>=100"}),". Tambi\xe9n pod\xe9s usar ",(0,s.jsx)(a.code,{children:"--tag"})," para desplegar una revisi\xf3n con una URL \xfanica (ej. ",(0,s.jsx)(a.code,{children:"--tag staging"}),") que permite testear antes de enrutar tr\xe1fico. Cloud Run maneja el traffic splitting a nivel de load balancer (Google Front End), sin sidecar ni service mesh. Para blue/green: 1) Deploy blue (actual) con 100%, 2) Deploy green con ",(0,s.jsx)(a.code,{children:"--no-traffic"}),", 3) Test green via tag URL, 4) Migrar tr\xe1fico: ",(0,s.jsx)(a.code,{children:"update-traffic --to-revisions green=100"}),". Rollback instant\xe1neo (vuelta a blue) sin re-deploy."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": Traffic splitting en Cloud Run es una feature nativa desde 2019. Internamente, Google Front End (GFE, el mismo load balancer que usa Google Search) distribuye las requests seg\xfan los pesos. No hay sidecars ni proxies adicionales. La migraci\xf3n de tr\xe1fico es instant\xe1nea (se actualiza la configuraci\xf3n del GFE en segundos). Esto es m\xe1s simple que Istio (Service Mesh) para blue/green."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"8-cuestionar-es-terraform-la-herramienta-correcta-para-gestionar-infraestructura-dockercloud-en-2025-o-pulumicrossplanecdktf-son-superiores",children:"8. [Cuestionar] \xbfEs Terraform la herramienta correcta para gestionar infraestructura Docker/cloud en 2025 o Pulumi/Crossplane/CDKTF son superiores?"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": Terraform (HCL) sigue siendo la herramienta m\xe1s madura y con mayor ecosistema de providers y m\xf3dulos. Es la elecci\xf3n segura y standard. Pulumi es superior si el equipo prefiere lenguajes de programaci\xf3n reales (TypeScript, Python, Go) sobre HCL \u2014 permite loops, conditionals, y abstracciones con las herramientas que ya conocen. Crossplane es superior si la organizaci\xf3n ya est\xe1 centrada en Kubernetes y quiere GitOps (los recursos cloud se definen como YAML, reconciliados por controladores). CDKTF (CDK for Terraform) permite escribir Terraform en TypeScript/Python (generando JSON de Terraform), combinando lo mejor de ambos mundos. La tendencia: Terraform para equipos DevOps tradicionales, Pulumi para equipos developer-centric, Crossplane para platform engineering sobre K8s."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': El debate "Terraform vs Pulumi vs Crossplane" es activo en la comunidad. Terraform (HashiCorp) cambi\xf3 su licencia a BSL (2023), lo que gener\xf3 el fork OpenTofu (Linux Foundation). Pulumi es open-source (Apache 2.0). Para Docker/cloud, Terraform sigue siendo el est\xe1ndar (el Docker provider y los cloud providers son maduros), pero Pulumi y OpenTofu est\xe1n ganando adopci\xf3n.']}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"9-cuestionar-deber\xedas-usar-un-solo-cloud-provider-para-tus-contenedores-o-adoptar-multi-cloud-desde-el-principio-cu\xe1ndo-vale-la-pena-la-complejidad-de-multi-cloud",children:"9. [Cuestionar] \xbfDeber\xedas usar un solo cloud provider para tus contenedores o adoptar multi-cloud desde el principio? \xbfCu\xe1ndo vale la pena la complejidad de multi-cloud?"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": Para la mayor\xeda de las empresas (startups, PyMEs, incluso grandes empresas que no son tech), single-cloud es suficiente y reduce complejidad operativa masivamente. Multi-cloud se justifica cuando: 1) Compliance/regulaci\xf3n (datos deben residir en pa\xeds espec\xedfico donde tu cloud primario no tiene regi\xf3n), 2) Estrategia de negocio (evitar vendor lock-in, poder de negociaci\xf3n con proveedores), 3) Adquisiciones/herencia (equipos que ya usan otro cloud), 4) Disaster recovery (segundo cloud como DR site), 5) Edge computing (diferentes ubicaciones geogr\xe1ficas con diferentes clouds). La complejidad de multi-cloud es alta: dos conjuntos de IAM, networking, monitoreo, CI/CD, y API diferentes. K8s ayuda a abstraer (EKS en AWS + GKE en GCP, misma aplicaci\xf3n), pero servicios gestionados alrededor de K8s (RDS vs Cloud SQL, ECR vs GAR, IAM) no son portables. Si no ten\xe9s una raz\xf3n fuerte, single-cloud es la mejor decisi\xf3n."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': La encuesta de Flexera (2024 State of the Cloud) muestra que el 89% de las empresas usan multi-cloud, PERO la mayor\xeda es "multi-cloud accidental" (diferentes equipos eligieron diferentes clouds) o "hybrid" (on-prem + un cloud). La estrategia de "multi-cloud activo-activo" (misma aplicaci\xf3n corriendo en 2 clouds simult\xe1neamente) es rara y costosa. Kelsey Hightower dijo: "Multi-cloud is not a strategy, it\'s an outcome".']}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"10-cuestionar-son-los-serverless-containers-cloud-run-fargate-el-futuro-o-kubernetes-gestionado-eks-gke-seguir\xe1-siendo-el-est\xe1ndar-para-aplicaciones-enterprise",children:'10. [Cuestionar] \xbfSon los "serverless containers" (Cloud Run, Fargate) el futuro, o Kubernetes gestionado (EKS, GKE) seguir\xe1 siendo el est\xe1ndar para aplicaciones enterprise?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),': Ambos coexistir\xe1n. Serverless containers son el futuro para aplicaciones stateless HTTP/gRPC y event-driven (la mayor\xeda de las nuevas aplicaciones). Kubernetes gestionado seguir\xe1 siendo el est\xe1ndar para: 1) Aplicaciones stateful complejas (bases de datos con operadores), 2) Plataformas que necesitan extensibilidad (CRDs, admission webhooks), 3) Organizaciones que ya invirtieron en K8s (equipos de plataforma, GitOps, tooling). La tendencia: K8s se est\xe1 volviendo invisible (GKE Autopilot, EKS Auto Mode, AKS Automatic) donde el proveedor gestiona el control plane y los nodos (similar a serverless), y los desarrolladores interact\xfaan con una capa PaaS (Cloud Run for GKE, Knative). La l\xednea entre "serverless containers" y "managed K8s" se est\xe1 difuminando. El futuro: la experiencia para el desarrollador ser\xe1 serverless (especific\xe1 imagen + resources, la plataforma gestiona el resto), y la plataforma subyacente ser\xe1 K8s (con Knative, Karpenter, y operadores).']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': Kubernetes co-founder Joe Beda (VMware) y Craig McLuckie (Google) han hablado sobre "Kubernetes disappearing into the infrastructure". GKE Autopilot (2021) y EKS Auto Mode (2024) son ejemplos: K8s sin gestionar nodos. Cloud Run for GKE (2022) ejecuta Knative sobre GKE, combinando serverless con K8s. La visi\xf3n a 5 a\xf1os: el desarrollador usa ',(0,s.jsx)(a.code,{children:"gcloud run deploy"})," (o equivalente), y debajo hay K8s gestionado + Knative + Karpenter, invisible para el desarrollador."]})]})}function u(e={}){const{wrapper:a}={...(0,r.R)(),...e.components};return a?(0,s.jsx)(a,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},28453(e,a,o){o.d(a,{R:()=>i,x:()=>t});var n=o(96540);const s={},r=n.createContext(s);function i(e){const a=n.useContext(r);return n.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function t(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:i(e.components),n.createElement(r.Provider,{value:a},e.children)}}}]);